-- Third batch of explicitly labelled supplemental study outlines for MBH histology.
-- Idempotent: existing answers are never overwritten.
with supplemental_answers(id, answer) as (
  values
  ('d75be7f0-e896-5e54-9d49-ee7eaef00044', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Эритроцит — гибкая двояковогнутая клетка без ядра и митохондрий, заполненная гемоглобином. Он переносит O2 и участвует в переносе CO2 и поддержании кислотно-основного равновесия. В норме эритроциты циркулируют около 120 дней; старые клетки удаляются преимущественно макрофагами селезёнки и печени. Ретикулоциты — молодые формы с остаточной рибосомальной РНК; их количество используют как показатель продукции эритроцитов. Нормальные количества зависят от пола, возраста и лабораторных критериев.'),
  ('ae59300b-3020-5fe3-a672-067e6de68a34', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Ткань — исторически сложившаяся система клеток и межклеточного вещества, объединённых общим происхождением, строением и функциями. Дифферон — ряд клеточных форм от стволовой/прогениторной клетки до зрелой дифференцированной клетки. В него могут входить стволовые, полустволовые клетки, пролиферирующие предшественники, созревающие и зрелые клетки. Численность регулируется балансом пролиферации, дифференцировки, гибели клеток, сигналами факторов роста, гормонов и микроокружения.'),
  ('6e8a54c8-e103-5501-a9c4-eaafdeb68223', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Кубический эпителий печёночных желчных канальцев формируют гепатоциты, соприкасающиеся апикальными поверхностями; сами канальцы не имеют отдельной стенки из самостоятельных эпителиоцитов. Мезотелий — однослойный плоский эпителий серозных оболочек, развивающийся из мезодермы боковой пластинки; он уменьшает трение и участвует в обмене жидкости. При распознавании печёночной ткани обращайте внимание на балки гепатоцитов и синусоиды; мезотелий выглядит как тонкий слой уплощённых клеток на поверхности соединительной ткани.'),
  ('049b5c9f-305c-5e85-afed-af2ddaec8c65', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Плотная неоформленная соединительная ткань содержит коллагеновые пучки в разных направлениях; это повышает устойчивость к разнонаправленным нагрузкам и характерно для дермы. Надкостница имеет наружный фиброзный слой с сосудами и нервами и внутренний остеогенный слой с клетками-предшественниками. Апоневрозы состоят из плотных упорядоченных коллагеновых пучков, распределяющих силу широкой пластинкой. Клеток сравнительно мало, преобладают фибробласты/фиброциты; матрикс богат коллагеном.'),
  ('82163a9f-79f7-5ffe-83ad-704169531d53', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Сухожилия и большинство связок — плотная оформленная соединительная ткань с параллельными или слегка волнистыми пучками коллагена I типа и рядами тендоцитов. Связки соединяют кости и ограничивают движения; некоторые содержат больше эластических волокон. Фасции — соединительнотканные оболочки, обычно с более разнонаправленными пучками, окружающие мышцы и органы. Во всех этих тканях основная нагрузка приходится на волокна; сосудистость относительно невысока, поэтому регенерация медленная.'),
  ('15fd4f1b-5564-5adb-92b4-75ed4e40c215', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Скелетное мышечное волокно — длинный многоядерный симпласт, окружённый сарколеммой и базальной мембраной; ядра расположены периферически. Саркомер ограничен Z-дисками; тонкие актиновые филаменты прикреплены к Z-дискам, толстые миозиновые расположены в центре. Ca2+ связывается с тропонином C, смещает тропомиозин и позволяет миозину взаимодействовать с актином. Различают окислительные медленные и быстрые волокна с разными метаболическими свойствами. Иннервация осуществляется нервно-мышечными синапсами.'),
  ('2edf5941-87bd-5635-b3b5-b8af462bb9e3', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Кишечный эпителий — однослойный цилиндрический; энтероциты обеспечивают всасывание, бокаловидные клетки выделяют слизь. В тонкой кишке ворсинки и микроворсинки увеличивают площадь всасывания; крипты содержат стволовые клетки, клетки Панета и энтероэндокринные клетки. В толстой кишке ворсинок нет, крипты многочисленны, бокаловидных клеток больше. Питание эпителия идёт диффузией из сосудов собственной пластинки; обновление обеспечивается клетками крипт.'),
  ('39314444-4fb2-59c5-a419-c0adffd246b5', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Многослойный плоский неороговевающий эпителий покрывает влажные поверхности, подверженные трению: пищевод, ротовую полость и влагалище. Базальные клетки делятся, промежуточные созревают, поверхностные остаются живыми и сохраняют ядра; роговой слой отсутствует. Эпителий защищает подлежащие ткани и поддерживает влажность поверхности. Он аваскулярен, питается диффузией из соединительной ткани; регенерация обеспечивается базальными клетками.'),
  ('7d13a41a-0cc5-58a4-9099-17649c75b0dc', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Сухожилие — плотная оформленная волокнистая соединительная ткань: параллельные пучки коллагена I типа ориентированы по линии нагрузки, между ними рядами лежат тендоциты/фиброциты. Пучки объединены эндотенонием, снаружи сухожилие окружено соединительнотканными оболочками. Основное вещество и сосуды выражены слабее, чем в рыхлой ткани; питание ограничено, поэтому восстановление после повреждения медленное. Функция — передача силы от мышцы к кости.'),
  ('0a6ef32d-d914-52fd-8ed4-09438ef0ff57', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Эритроциты человека — безъядерные двояковогнутые диски с гемоглобином; форма увеличивает площадь обмена и позволяет деформироваться в капиллярах. Основные функции — перенос кислорода и части углекислого газа, участие в буферных системах. Созревание сопровождается потерей ядра и большинства органелл. Ретикулоциты — молодые эритроциты с остаточной РНК, выявляемой специальной окраской; их доля отражает активность эритропоэза. Продолжительность жизни зрелого эритроцита у человека в среднем около 120 дней.'),
  ('514e7ed0-ec0d-5e54-af05-1976f74c1f1a', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Кровь — жидкая соединительная ткань, состоящая из плазмы и форменных элементов: эритроцитов, лейкоцитов и тромбоцитов. Тромбоциты — безъядерные фрагменты мегакариоцитов, обычно живут около 7–10 дней (значения могут варьировать), участвуют в адгезии, агрегации и первичном гемостазе. В мазке видны небольшие фрагменты с грануломером и гиаломером. Их количество оценивают по лабораторным референсным диапазонам; в гистологическом ответе важны происхождение, строение и функция.'),
  ('a2870612-6b02-5084-8ac3-b313c458adb6', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Основные группы тканей организма: эпителиальные, соединительные (включая кровь), мышечные и нервная. Компоненты — клетки и внеклеточный матрикс, количество которого сильно различается между тканями. Симпласт — многоядерная структура общей цитоплазмы, возникающая при слиянии клеток (пример — скелетное мышечное волокно). Межклеточное вещество включает основное вещество и волокна; оно обеспечивает опору, механические свойства, диффузию и сигнальные взаимодействия.'),
  ('55643d24-e09e-5fcb-a511-06280bb62caa', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Переходный эпителий (уротелий) выстилает мочевыводящие пути от чашечек и лоханки до мочевого пузыря. Он состоит из базальных, промежуточных и поверхностных зон; крупные поверхностные клетки образуют барьер, устойчивый к моче. При растяжении число визуально различимых слоёв уменьшается, поверхностные клетки уплощаются. Диагностические признаки — многослойность, куполообразные зонтичные клетки и отсутствие ороговения.'),
  ('c20b4350-ad05-5aaa-b39b-80a70c664584', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Скелетная мышца как орган включает мышечные волокна, соединительнотканные оболочки (эндомизий, перимизий, эпимизий), сосуды и нервы. Волокно содержит миофибриллы из повторяющихся саркомеров между Z-дисками; взаимодействие актина и миозина вызывает укорочение саркомера при наличии Ca2+ и АТФ. Сателлитные клетки располагаются между сарколеммой и базальной мембраной и участвуют в восстановлении. После значительного повреждения полная регенерация ограничена и может формироваться рубец.'),
  ('8f4c3d88-11cf-5ccb-a536-bfdc17680330', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). По морфологии эпителий классифицируют по числу слоёв и форме поверхностных клеток; функционально — на покровный, железистый и специализированный (например, сенсорный). Генетическая классификация учитывает источник развития: эпителии могут происходить из эктодермы, энтодермы или мезодермы в зависимости от органа. Основные функции — барьерная, секреторная, всасывательная, транспортная и рецепторная. Для полного ответа приведите примеры локализации и диагностические признаки каждого типа.'),
  ('f48fa764-35d2-5bd0-b7d3-10a0ae859402', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Скелетная мышечная ткань развивается из миогенных клеток мезодермы, которые сливаются в длинные многоядерные волокна с периферическими ядрами. Миофибриллы состоят из саркомеров — повторяющихся участков между Z-дисками; тонкие актиновые и толстые миозиновые филаменты скользят друг относительно друга при участии Ca2+ и АТФ. Волокна различаются по метаболизму и скорости сокращения. Регенерация ограничена сателлитными клетками, а при значительном повреждении образуется рубцовая ткань.'),
  ('8c4a7583-47c1-54f5-98a9-f953f368b800', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Сердечная мышечная ткань состоит из ветвящихся кардиомиоцитов с одним или двумя центральными ядрами, поперечной исчерченностью и вставочными дисками. Вставочные диски содержат механические контакты и щелевые соединения, обеспечивающие согласованное сокращение. Кардиомиоциты богаты митохондриями и капиллярами; проводящая система включает специализированные клетки. Регенерация зрелого миокарда ограничена, повреждённые участки обычно замещаются соединительной тканью.'),
  ('f651940f-1a59-5f69-b9fc-b4bd2930f09a', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Иммунная система включает центральные органы (красный костный мозг и тимус) и периферические (лимфатические узлы, селезёнка, миндалины и лимфоидную ткань слизистых). B-лимфоциты после активации могут превращаться в плазмоциты и клетки памяти; T-хелперы координируют ответ, цитотоксические T-клетки уничтожают инфицированные клетки, регуляторные T-клетки ограничивают реакцию; NK-клетки обеспечивают врождённую цитотоксичность. Эффективный ответ зависит от взаимодействия антигенпредставляющих клеток, лимфоцитов и цитокинов.'),
  ('03c068d2-ec2a-5484-857b-17085b1f5cfb', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Волокнистые соединительные ткани развиваются преимущественно из мезенхимы и включают клетки, волокна и основное вещество. Рыхлая ткань содержит разнообразные клетки и много основного вещества; плотная содержит преобладающие пучки коллагена и меньше клеток. Плотная оформленная ткань имеет параллельные пучки (сухожилия), неоформленная — разнонаправленные пучки (дерма). Основные клетки — фибробласты/фиброциты; также встречаются макрофаги, тучные клетки, плазмоциты, лейкоциты и адипоциты. Коллаген сопротивляется растяжению, эластические волокна обеспечивают обратимое растяжение.'),
  ('b009dea0-0cb7-5129-8497-4990409337d4', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Нервные окончания бывают рецепторными и эффекторными. Рецепторные воспринимают раздражение и преобразуют его в сигнал; они классифицируются по расположению, виду стимула и строению (свободные, неинкапсулированные, инкапсулированные). Эффекторные окончания передают сигнал мышцам или железам. Нервно-мышечный синапс скелетной мышцы (моторная бляшка) включает пресинаптическое окончание мотонейрона с везикулами ацетилхолина, синаптическую щель с базальной мембраной и постсинаптические складки сарколеммы с никотиновыми холинорецепторами.')
)
update public.exam_questions q
set answer = s.answer, updated_at = now()
from supplemental_answers s
where q.id = s.id::uuid
  and q.subject_slug = 'histology'
  and nullif(btrim(q.answer), '') is null;
